#!/usr/bin/env bash
# Probe job (generated by nmprobe.sh; runs on MSI).  Under the clone's lock:
# export origin/main@SHA once (shared, from the MSI mirror), make the clone's
# GroupApproximation/ equal to that export EXCEPT the lane's overlay paths,
# apply the overlay, run the transitive stale purge, build the named modules.
# So a GREEN certifies exactly  origin/main@SHA + the overlay bytes.
set -u
P=/projects/standard/__MSI_GROUP__/__MSI_USER__
export HOME=$P ELAN_HOME=$P/.elan XDG_CACHE_HOME=$P/.cache PATH=$P/.elan/bin:$PATH
CLONE=__CLONE__; TAG=__TAG__; SHA=__SHA__; MODS="__MODS__"
NMR=$P/nm
LOG=$CLONE/.nm/build-$TAG.log
export LEAN_NUM_THREADS=${NT:-8}
summary_fail() { echo "===== SUMMARY"; echo "$1"; exit "${2:-4}"; }
exec 9>"$CLONE/.lake/laneprobe.lock"
echo "[job] $(date +%T) $(hostname -s) waiting for clone lock"
flock -w 14400 9 || summary_fail "PROBE FAILED: clone lock not free after 4 h (infra)" 3
[ -e "$CLONE/.nm/PREP_PENDING" ] && summary_fail "PROBE DEFERRED: clone preparation in progress (base warm build + artifact copy). Author meanwhile; retry in ~15 min." 5
# Source sync (20:50 fix): DELTA from the clone's last base SHA (git diff in the MSI mirror, only
# changed files rewritten, no global lock); the full per-SHA export is only a fallback.
exec 8>"$NMR/mirror.lock"; flock -w 900 8 || summary_fail "PROBE FAILED: mirror lock busy (infra)"
git -C "$NMR/mirror.git" fetch -q origin 2>/dev/null
exec 8>&-
git -C "$NMR/mirror.git" cat-file -e "$SHA^{commit}" || summary_fail "PROBE FAILED: MSI mirror lacks $SHA (infra)"
OV=$CLONE/.nm/ov-$TAG
( cd "$OV" && find . -type f -name '*.lean' | sed 's|^\./||' ) | sort > "$CLONE/.nm/ovpaths-$TAG"
sed 's|^GroupApproximation/|/|' "$CLONE/.nm/ovpaths-$TAG" > "$CLONE/.nm/excl-$TAG"
LAST=$(cat "$CLONE/.nm/base" 2>/dev/null)
[ -n "$LAST" ] || LAST=$(grep -ho 'base=[0-9a-f]\{40\}' "$CLONE"/.nm/build-*.log 2>/dev/null | tail -1 | cut -d= -f2)
MODE=full
if [ -n "$LAST" ] && git -C "$NMR/mirror.git" cat-file -e "$LAST^{commit}" 2>/dev/null; then
  MODE=delta
  touch "$CLONE/.nm/lastov"
  { comm -23 <(sort "$CLONE/.nm/lastov") "$CLONE/.nm/ovpaths-$TAG";
    git -C "$NMR/mirror.git" diff --name-only --no-renames "$LAST" "$SHA" -- GroupApproximation GroupApproximation.lean; } \
    | sort -u | comm -23 - "$CLONE/.nm/ovpaths-$TAG" > "$CLONE/.nm/todo-$TAG"
  nchg=0
  while IFS= read -r path; do
    [ -n "$path" ] || continue
    if git -C "$NMR/mirror.git" cat-file -e "$SHA:$path" 2>/dev/null; then
      mkdir -p "$CLONE/$(dirname "$path")"
      git -C "$NMR/mirror.git" show "$SHA:$path" > "$CLONE/$path.nmtmp" || summary_fail "PROBE FAILED: delta sync (infra)"
      if cmp -s "$CLONE/$path.nmtmp" "$CLONE/$path"; then rm -f "$CLONE/$path.nmtmp"; else mv "$CLONE/$path.nmtmp" "$CLONE/$path"; nchg=$((nchg+1)); fi
    elif [ -e "$CLONE/$path" ]; then
      rm -f "$CLONE/$path"; nchg=$((nchg+1))
    fi
  done < "$CLONE/.nm/todo-$TAG"
  echo "[job] delta sync ${LAST:0:9}..${SHA:0:9}: $nchg files changed"
fi
if [ "$MODE" = full ]; then
  mkdir -p "$NMR/exports"
  EXP=$NMR/exports/$SHA
  if [ ! -e "$EXP/.done" ]; then
    exec 8>"$NMR/exports/.lock"; flock -w 1800 8
    if [ ! -e "$EXP/.done" ]; then
      rm -rf "$EXP.tmp"; mkdir -p "$EXP.tmp"
      git -C "$NMR/mirror.git" archive "$SHA" GroupApproximation GroupApproximation.lean scripts | tar -x -C "$EXP.tmp" || summary_fail "PROBE FAILED: export (infra)"
      touch "$EXP.tmp/.done"; mv "$EXP.tmp" "$EXP"
    fi
    exec 8>&-
  fi
  rsync -rlc --delete --exclude-from="$CLONE/.nm/excl-$TAG" "$EXP/GroupApproximation/" "$CLONE/GroupApproximation/" || summary_fail "PROBE FAILED: source sync (infra)"
  rsync -lc "$EXP/GroupApproximation.lean" "$CLONE/GroupApproximation.lean"
  echo "[job] full export sync at ${SHA:0:9}"
fi
rsync -rlc "$OV/" "$CLONE/" || summary_fail "PROBE FAILED: overlay apply (infra)"
cp "$CLONE/.nm/ovpaths-$TAG" "$CLONE/.nm/lastov"
echo "$SHA" > "$CLONE/.nm/base"
cd "$CLONE" || summary_fail "PROBE FAILED: no clone (infra)"
python3 "$NMR/purge_stale_nm.py" "$CLONE" > "$LOG" 2>&1
# USER ORDER 09-11 21:40 "we dont need to compile same code a billion times": one shared Lake artifact cache
# for every nm clone (content-addressed by input hash), artifacts hard-linked back into the build dir.
export LAKE_ARTIFACT_CACHE=true LAKE_RESTORE_ARTIFACTS=true LAKE_CACHE_DIR="$NMR/lake-cache"
TS=""; [ -n "${CORES:-}" ] && TS="taskset -c $CORES"
echo "[job] $(hostname -s) cores=${CORES:-slurm} threads=$LEAN_NUM_THREADS base=$SHA mods: $MODS" >> "$LOG"
timeout 10800 nice -n 5 $TS lake build $MODS >> "$LOG" 2>&1; RC=$?
echo "EXIT=$RC" >> "$LOG"
echo "===== SUMMARY"
echo "host $(hostname -s) cores ${CORES:-slurm} base ${SHA:0:9} log $LOG"
head -1 "$LOG"
echo "--- errors (first 80 lines)"
grep -n -E '^error|error:|✖|declaration uses .sorry.|sorryAx' "$LOG" | head -80
echo "--- per-module"
for m in $MODS; do
  if grep -qF "Built $m " "$LOG" || grep -qE "Built ${m//./\\.}$" "$LOG"; then echo "BUILT $m"
  elif grep -qF " $m" "$LOG"; then echo "mentioned-not-built $m (replayed or failed)"
  else echo "NOT-REACHED $m"; fi
done
echo "--- rebuilt GroupApproximation modules: $(grep -c 'Built GroupApproximation' "$LOG")"
echo "--- compiled overlay files (olean present; olean/.trace/.olean.hash newer than the source as built; a cache restore counts: same input hash)"
while IFS= read -r rel; do
  p="GroupApproximation$rel"; b=".lake/build/lib/lean/${p%.lean}"
  if [ -f "$b.olean" ] && { [ "$b.olean" -nt "$p" ] || [ "$b.trace" -nt "$p" ] || [ "$b.olean.hash" -nt "$p" ]; }; then echo "COMPILED $p"; fi
done < "$CLONE/.nm/excl-$TAG"
tail -3 "$LOG"
if [ $RC -eq 0 ] && grep -q 'Build completed successfully' "$LOG"; then echo "PROBE GREEN"; else echo "PROBE FAILED rc=$RC"; fi
rm -rf "$OV" "$CLONE/.nm/excl-$TAG"
exit $RC
